        { id: 'vice', name: 'Vice-Governador', ticket: 2000, implantation: 5000, clients: 0, target: 0 },
    ]);
    setStartMonth(0);
    setChurnRate(3);
  };

  // --- FORMATTERS ---
  const formatMoney = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(val);

  return (
