  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine,
  BarChart, Bar, Cell, PieChart, Pie
} from 'recharts';

interface LevelInput {
  id: string;
  name: string;
  ticket: number;
  implantation: number;
  clients: number;
}

const RoadmapCalculator: React.FC = () => {
  // --- STATE ---
  const [startMonth, setStartMonth] = useState(0); // 0 = Jan, 1 = Feb...
  const [churnRate, setChurnRate] = useState(3);
  const [operationalCosts, setOperationalCosts] = useState(25000); // Fixed monthly cost
  const [annualGoal] = useState(1006200); // Validated 2026 Revenue Goal
  const [targetValuation] = useState(4800000); // Validated Target Valuation

  const [levels, setLevels] = useState<LevelInput[]>([
    { id: 'ver', name: 'Vereador', ticket: 149, implantation: 0, clients: 120 },
    { id: 'est', name: 'Dep. Estadual', ticket: 399, implantation: 500, clients: 30 },
    { id: 'fed', name: 'Dep. Federal', ticket: 799, implantation: 1500, clients: 10 },
    { id: 'pref', name: 'Prefeito', ticket: 1200, implantation: 3000, clients: 5 },
    { id: 'sen', name: 'Senador', ticket: 2500, implantation: 5000, clients: 0 },
    { id: 'gov', name: 'Governador', ticket: 5000, implantation: 15000, clients: 0 },
    { id: 'vice', name: 'Vice-Governador', ticket: 2000, implantation: 5000, clients: 0 },
  ]);

  // --- CALCULATIONS ---

  const calculateKPIs = () => {
    let totalMRR = 0;
    let totalImplementation = 0;
    let totalClients = 0;
    let annualRevenue = 0; // Total (Sub + Impl)
    let annualSubscriptionRevenue = 0; // Just Sub

    levels.forEach(lvl => {
      totalMRR += lvl.ticket * lvl.clients;
      totalImplementation += lvl.implantation * lvl.clients;
      totalClients += lvl.clients;

      const monthsActive = 12 - startMonth;
      const subRev = lvl.ticket * lvl.clients * monthsActive;
      const implRev = lvl.implantation * lvl.clients;

      annualSubscriptionRevenue += subRev;
      annualRevenue += (subRev + implRev);
    });

    const weightedTicket = totalClients > 0 ? totalMRR / totalClients : 0;
    const arr = totalMRR * 12; // Annual Recurring Revenue

    // Formulas
    const cac = 150; // Fixed from prompt
    const ltv = churnRate > 0 ? weightedTicket * (1 / (churnRate / 100)) : 0;
    const payback = weightedTicket > 0 ? cac / weightedTicket : 0;

    // Total Costs (Annual)
    const totalCosts = operationalCosts * 12;
    const profit = annualRevenue - totalCosts;
    const margin = annualRevenue > 0 ? (profit / annualRevenue) * 100 : 0;

    // Valuation Logic
    // Based on Realistic Multiple of 4x ARR + 1.2M Assets
    const currentValuation = (arr * 4) + 1200000;

    return {
      totalMRR,
      arr,
      totalImplementation,
      totalClients,
      annualRevenue,
      annualSubscriptionRevenue,
      weightedTicket,
      ltv,
      cac,
      payback,
      margin,
      currentValuation
    };
  };

  const kpis = calculateKPIs();

  // --- CHART DATA GENERATION ---
  const generateChartData = () => {
    const data = [];
    let cumulativeRealist = 0;
    const months = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun', 'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez'];

    for (let i = 0; i < 12; i++) {
      let monthRevenueBase = 0;
      if (i >= startMonth) {
        monthRevenueBase = levels.reduce((acc, lvl) => acc + (lvl.ticket * lvl.clients), 0);
        if (i === startMonth) {
          monthRevenueBase += levels.reduce((acc, lvl) => acc + (lvl.implantation * lvl.clients), 0);
        }
      }
      cumulativeRealist += monthRevenueBase;
      data.push({
        name: months[i],
        Realista: cumulativeRealist,
        Goal: annualGoal,
      });
    }
    return data;
  };

  const chartData = generateChartData();

  // --- HANDLERS ---
  const handleLevelChange = (id: string, field: keyof LevelInput, value: number) => {
    setLevels(prev => prev.map(lvl => lvl.id === id ? { ...lvl, [field]: value } : lvl));
  };

  const formatMoney = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(val);

  return (
    <div className="space-y-10 animate-in fade-in duration-500 pb-20">

      {/* HEADER */}
      <div className="flex justify-between items-center border-b border-gray-200 pb-5">
        <div>
          <span className="text-[10px] text-red-600 font-bold uppercase tracking-wider mb-1 block">* destinado equipe interna</span>
          <h2 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
            <Rocket className="text-indigo-600" /> Simulador 2026
          </h2>
          <p className="text-gray-500 mt-2">Planejamento financeiro e projeção de múltiplos (Valuation).</p>
        </div>
        <div className="flex gap-2">
           <button onClick={() => window.print()} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 transition-all">
             <Download size={16} /> Exportar
           </button>
           <button onClick={() => setLevels(prev => [...prev])} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-indigo-600 bg-white border border-gray-300 rounded-lg hover:bg-indigo-50 transition-all">
             <RefreshCcw size={16} /> Recalcular
           </button>
        </div>
      </div>

      {/* 1. TOP KPIs WITH VALUATION CONNECTION */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="bg-indigo-700 text-white p-6 rounded-2xl shadow-xl relative overflow-hidden group">
              <div className="absolute -right-4 -bottom-4 opacity-10 group-hover:scale-110 transition-transform">
                <Calculator size={80} />
              </div>
              <p className="text-indigo-200 text-xs font-bold uppercase mb-1">Valuation Projetado</p>
              <p className="text-3xl font-black">{formatMoney(kpis.currentValuation)}</p>
              <div className="mt-3 flex items-center gap-2">
                <span className={`text-[10px] font-bold px-2 py-1 rounded uppercase ${kpis.currentValuation >= targetValuation ? 'bg-green-500/20 text-green-300' : 'bg-yellow-500/20 text-yellow-300'}`}>
                  {kpis.currentValuation >= targetValuation ? 'Meta Atingida' : 'Abaixo do Target'}
                </span>
                <span className="text-[10px] opacity-60">Target: {formatMoney(targetValuation)}</span>
              </div>
          </div>

          <div className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm">
              <p className="text-gray-400 text-xs font-bold uppercase mb-1">Receita Total 2026</p>
              <p className="text-3xl font-bold text-gray-900">{formatMoney(kpis.annualRevenue)}</p>
              <div className="mt-3 h-1.5 w-full bg-gray-100 rounded-full overflow-hidden">
                <div className="h-full bg-indigo-600" style={{ width: `${Math.min(100, (kpis.annualRevenue / annualGoal) * 100)}%` }}></div>
              </div>
              <p className="text-[10px] text-gray-500 mt-2">Objetivo: {formatMoney(annualGoal)}</p>
          </div>

          <div className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm">
              <p className="text-gray-400 text-xs font-bold uppercase mb-1">MRR Acumulado</p>
              <p className="text-3xl font-bold text-gray-900">{formatMoney(kpis.totalMRR)}</p>
              <p className="text-xs text-green-600 font-bold mt-2 flex items-center gap-1">
                <Users size={12}/> {kpis.totalClients} Mandatos Ativos
              </p>
          </div>

          <div className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm">
              <p className="text-gray-400 text-xs font-bold uppercase mb-1">Unit Economics</p>
              <p className="text-3xl font-bold text-blue-600">{(kpis.ltv / kpis.cac).toFixed(1)}x</p>
              <p className="text-xs text-gray-500 mt-2">LTV/CAC (Saúde Financeira)</p>
          </div>
      </div>

      {/* 2. CALCULATION CORE */}
      <section className="bg-white rounded-2xl p-8 border border-gray-200 shadow-sm">
         <div className="flex flex-col lg:flex-row gap-8">
            {/* Table Inputs */}
            <div className="flex-1 overflow-hidden">
                <h3 className="text-lg font-bold text-gray-800 mb-6 flex items-center gap-2">
                   <Layers size={20} className="text-indigo-600" /> Matriz de Clientes (RS/SC)
                </h3>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-gray-50 text-gray-500 font-bold uppercase text-[10px] tracking-widest border-b border-gray-100">
                            <tr>
                                <th className="px-4 py-3">Nível / Cargo</th>
