                                <th className="px-4 py-3 text-center">Volume</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-50">
                            {levels.map((lvl) => (
                                <tr key={lvl.id} className="hover:bg-indigo-50/30 transition-colors">
                                    <td className="px-4 py-4 font-bold text-gray-900">{lvl.name}</td>
                                    <td className="px-4 py-4 text-right">
                                        <input 
