                                            value={lvl.ticket} 
                                            onChange={(e) => handleLevelChange(lvl.id, 'ticket', parseFloat(e.target.value))}
                                            className="w-20 text-right border border-gray-200 rounded px-2 py-1 bg-gray-50 focus:bg-white focus:ring-2 focus:ring-indigo-500 outline-none"
                                        />
                                    </td>
                                    <td className="px-4 py-4 text-right">
