                                <th className="px-4 py-3 text-center">Clientes</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-50">
                            {levels.map((lvl) => (
                                <tr key={lvl.id} className="hover:bg-indigo-50/30">
