                          <input type="range" min="0" max="5" step="1" value={startMonth} onChange={(e) => setStartMonth(parseInt(e.target.value))} className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-indigo-600" />
